document.addEventListener("DOMContentLoaded",function(){const n=document.getElementById("mobileMenuToggle"),t=document.getElementById("navMenu");if(n&&t){n.addEventListener("click",function(){const r=t.classList.toggle("active");n.setAttribute("aria-expanded",r);const i=n.querySelector("i");i&&(r?(i.classList.remove("fa-bars"),i.classList.add("fa-times")):(i.classList.remove("fa-times"),i.classList.add("fa-bars")))});const i=t.querySelectorAll("a");i.forEach(i=>{i.addEventListener("click",function(){if(t.classList.contains("active")){t.classList.remove("active");n.setAttribute("aria-expanded","false");const i=n.querySelector("i");i&&(i.classList.remove("fa-times"),i.classList.add("fa-bars"))}})});document.addEventListener("click",function(i){const r=t.contains(i.target),u=n.contains(i.target);if(!r&&!u&&t.classList.contains("active")){t.classList.remove("active");n.setAttribute("aria-expanded","false");const i=n.querySelector("i");i&&(i.classList.remove("fa-times"),i.classList.add("fa-bars"))}})}});